rollback.sql:
DELETE FROM nlp_configuration
WHERE property_key = 'nl-portal.config.documentenapis.properties.vertrouwelijkheidsaanduiding-whitelist'
  AND EXISTS (SELECT 1 FROM nlp_configuration WHERE property_key = 'nl-portal.config.zakenapi.properties.zaak-documenten-config.vertrouwelijkheidsaanduiding-whitelist');

DELETE FROM nlp_configuration
WHERE property_key = 'nl-portal.config.documentenapis.properties.status-whitelist'
  AND EXISTS (SELECT 1 FROM nlp_configuration WHERE property_key = 'nl-portal.config.zakenapi.properties.zaak-documenten-config.status-whitelist');

DELETE FROM nlp_configuration
WHERE property_key = 'nl-portal.frontend.theme.logo'
  AND EXISTS (SELECT 1 FROM nlp_configuration WHERE property_key = 'nl-portal.config.theme.logo');

DELETE FROM nlp_configuration
WHERE property_key = 'nl-portal.frontend.theme.style'
  AND EXISTS (SELECT 1 FROM nlp_configuration WHERE property_key = 'nl-portal.config.theme.style');

changeSet.sql:
UPDATE nlp_configuration SET property_value = REPLACE(property_value, '-', '_')
WHERE property_key LIKE 'nl-portal.config.payment.direct.properties.configurations.%.language'
  AND property_value IN ('nl-NL', 'en-GB');

